<?php
require 'config/database.php';require 'helpers/functions.php';login_required();
if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$pid=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);$type=$_POST['type']??'';$qty=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);$note=trim($_POST['note']??'');try{if(!$pid||!in_array($type,['IN','OUT'],true)||!$qty||$qty<1)throw new RuntimeException('Jumlah minimal 1 dan data harus valid.');$pdo->beginTransaction();$s=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$s->execute([$pid]);$p=$s->fetch();if(!$p)throw new RuntimeException('Produk tidak ditemukan.');if($type==='OUT'&&(int)$p['stock']<$qty)throw new RuntimeException('Stok tidak mencukupi.');$new=$type==='IN'?(int)$p['stock']+$qty:(int)$p['stock']-$qty;$u=$pdo->prepare('UPDATE products SET stock=? WHERE id=?');$u->execute([$new,$pid]);$m=$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,note) VALUES(?,?,?,?,?)');$m->execute([$pid,$_SESSION['user']['id'],$type,$qty,$note?:null]);$pdo->commit();msg('Transaksi berhasil.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();msg($e->getMessage(),'error');}go('stock.php');}
$products=$pdo->query('SELECT id,sku,name,stock FROM products ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT m.*,p.sku,p.name product,u.name username FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN users u ON u.id=m.user_id ORDER BY m.created_at DESC LIMIT 100')->fetchAll();header_html('Transaksi Stok');echo '<section><h2>Catat transaksi</h2><form method="post" class="grid"><input type="hidden" name="csrf" value="'.e(token()).'"><div><label>Produk</label><select name="product_id" required>';foreach($products as $p)echo '<option value="'.e($p['id']).'">'.e($p['sku'].' - '.$p['name'].' (stok '.$p['stock'].')').'</option>';echo '</select></div><div><label>Jenis</label><select name="type"><option value="IN">Stok Masuk</option><option value="OUT">Stok Keluar</option></select></div><div><label>Jumlah</label><input type="number" name="quantity" min="1" required></div><div><label>Catatan</label><input name="note" maxlength="255"></div><button>Simpan</button></form></section><section><h2>Riwayat (100 terbaru)</h2><table><tr><th>Waktu</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Petugas</th><th>Catatan</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['sku'].' '.$r['product']).'</td><td>'.($r['type']==='IN'?'Masuk':'Keluar').'</td><td>'.e($r['quantity']).'</td><td>'.e($r['username']??'-').'</td><td>'.e($r['note']).'</td></tr>';echo '</table></section>';footer_html();
